import React, { useEffect, useState } from "react";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { IconButton } from "@mui/material";
import { useNavigate, useLocation } from "react-router-dom";
import http from "../../services/utility";
import { apisPath } from "../../utils/path";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import { useDispatch } from "react-redux";

export default function AddNewSubCategory() {
  const dispatch = useDispatch();
  const { state } = useLocation();
  const [data, setData] = useState(state?.data);
  const [addNewSubCat, setAddNewSubCat] = useState(state?.addSubCat);
  const [catId, setCatId] = useState(state?.catId);

  const navigate = useNavigate();
  const [dropData, setDropData] = useState([]);
  const [newCatName, setNewCatName] = useState("");

  useEffect(() => {
    getData();
    // If editing a specific subcategory, pre-fill the input
    if (!addNewSubCat && data) {
      setNewCatName(data.name);
    }
  }, [data, addNewSubCat]);

  const getData = async () => {
    await http
      .get(`${apisPath?.admin?.subcategories}/${catId}`)
      .then(async (res) => {
        // console.log(res?.data?.subcategories);
        setDropData((prev) => res?.data?.subcategories);
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const uploadData = async () => {
    // If editing a specific subcategory
    if (!addNewSubCat && data) {
      const formData = {
        id: data.id,
        name: newCatName,
      };

      await http
        .put("https://api.bignlean.com/admin/subcategories", formData)
        .then((res) => {
          dispatch(
            openSuccessTicker({ title: "Success", body: res?.data?.message })
          );
          navigate(-1);
        })
        .catch((err) => {
          dispatch(
            openTicker({ title: "Error", body: err?.response?.data?.message })
          );
        });
    } else {
      // Adding new subcategory
      const formData = {
        name: newCatName,
        catId: catId,
      };

      await http
        .post(apisPath?.admin?.subcategories, formData)
        .then((res) => {
          dispatch(
            openSuccessTicker({ title: "Success", body: res?.data?.message })
          );
          navigate(-1);
        })
        .catch((err) => {
          dispatch(
            openTicker({ title: "Error", body: err?.response?.data?.message })
          );
        });
    }
  };

  const deleteData = async (index) => {
    await http
      .delete(`${apisPath?.admin?.subcategories}?id=${index}`)
      .then(async (res) => {
        // console.log(res?.data?.message);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const updateData = async (index, subCatId) => {
    let listData = dropData[index];
    const formData = {
      id: subCatId,
      name: listData?.name,
    };

    await http
      .put("https://api.bignlean.com/admin/subcategories", formData)
      .then(async (res) => {
        // console.log(res?.data?.message);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const handleInputChange = async (e, index) => {
    let listData = [...dropData];
    listData[index]["name"] = e?.target?.value;
    setDropData(listData);
  };

  return (
    <div className="add_new_sub_category">
      <div className="detail__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">
          {!addNewSubCat && data ? `Edit Sub Category` : "Add New Sub Category"}
        </h3>
      </div>
      <div className="add_new_sub_category__content">
        {/* Edit form for specific subcategory */}
        {!addNewSubCat && data ? (
          <div className="add_new_sub_category__content__sub_category_name">
            <div className="add_new_sub_category__content__sub_category_name__input">
              <label htmlFor="category_name">Sub category name</label>
              <input
                type="text"
                id="category_name"
                placeholder="Enter here"
                value={newCatName}
                maxLength={50}
                onChange={(e) => setNewCatName(e?.target?.value)}
              />
              <small style={{ color: '#666', fontSize: '12px' }}>
                {newCatName?.length || 0}/50 characters
              </small>
            </div>
            <button className="button-red" onClick={uploadData}>
              Update Sub Category
            </button>
          </div>
        ) : (
          /* Add new subcategory form */
          <>
            <div className="add_new_sub_category__content__sub_category_name">
              <div className="add_new_sub_category__content__sub_category_name__input">
                <label htmlFor="category_name">Sub category name</label>
                <input
                  type="text"
                  id="category_name"
                  placeholder="Enter here"
                  maxLength={50}
                  onChange={(e) => setNewCatName(e?.target?.value)}
                />
                <small style={{ color: '#666', fontSize: '12px' }}>
                  {newCatName?.length || 0}/50 characters
                </small>
              </div>
              <button className="button-red" onClick={uploadData}>
                Add Sub Category
              </button>
            </div>

            {/* List view for managing existing subcategories */}
            {!addNewSubCat && (
              <div className="add_new_sub_category__content__sub_category_list">
                <h4 className="add_new_sub_category__heading page_subheading">
                  Sub category list
                </h4>
                <div className="add_new_sub_category__content__sub_category_list__content">
                  {dropData?.map((item, index) => {
                    return (
                      <div
                        className="add_new_sub_category__content__sub_category_list__content__item"
                        key={index}
                      >
                        <input
                          type="text"
                          placeholder={item?.name}
                          value={item?.name}
                          onChange={(e) => handleInputChange(e, index)}
                          onBlur={() => updateData(index, item?.id)}
                        />
                        <button
                          className="button-red"
                          onClick={() => deleteData(item?.id)}
                        >
                          Delete
                        </button>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}
